UPDATE SW_SEFAZPI.FOLHA_FUNC_RUBRICA_IMPORTADA -- AUDITOR FISCAL DA FAZENDA ESTADUAL
SET VALOR_MULTIPLICADOR = 8400
WHERE ID_RUBRICA_IMPORTADA IN (
    SELECT
        RI.ID_RUBRICA_IMPORTADA
    FROM SW_SEFAZPI.FOLHA_FUNC_RUBRICA_IMPORTADA RI
        JOIN SW_SEFAZPI.FOLHA FO ON FO.ID_FOLHA = RI.ID_FOLHA_VALORES
        JOIN SW_SEFAZPI.FOLHA_FUNC_PERFIL FP ON FP.ID_FOLHA_FUNCIONARIO = RI.ID_FOLHA_FUNCIONARIO
        JOIN SW_SEFAZPI.FOLHA_FUNC_REFERENCIA FR ON FR.ID_FOLHA_PERFIL = FP.ID_FOLHA_PERFIL
        JOIN SW_SEFAZPI.FUNCIONARIO_REFERENCIA R ON R.ID_FUNCIONARIO_REFERENCIA = FR.ID_FUNCIONARIO_REFERENCIA
    WHERE
        FO.MES = 7 AND
        FO.ANO = 2026 AND
        RI.ID_RUBRICA IN (1555799, 1555800, 1555346, 1559130, 1556100, 1559131, 1556099, 1561591) AND
        R.ID_CATEGORIA_FUNCIONAL = 2 AND
        RI.VALOR_MULTIPLICADOR <> 8400
);

