        JOIN SW_SEFAZPI.FOLHA_FUNC_REFERENCIA FR ON FR.ID_FOLHA_PERFIL = FP.ID_FOLHA_PERFIL
        JOIN SW_SEFAZPI.FUNCIONARIO_REFERENCIA R ON R.ID_FUNCIONARIO_REFERENCIA = FR.ID_FUNCIONARIO_REFERENCIA
    WHERE
