-- Cedidos
SELECT
    DISTINCT
    PAG.ORGAO,
    PAG.CHAVE_FOLHA,
    PV.COD_INSTITUCIONAL,
    PAG.VALOR_MULTIPLICADOR,
    'UPDATE SW_' || PAG.ORGAO || '.FOLHA_FUNC_RUBRICA_IMPORTADA SET VALOR_MULTIPLICADOR = ' AS Q_1,
    CASE
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 2 THEN '8400'   -- AUDITOR FISCAL DA FAZENDA ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 3 THEN '2880'      -- AUDITOR FISCAL AUXILIAR DA FAZENDA ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 4 THEN '1620'      -- AGENTE DE TRIBUTOS DA FAZENDA ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 5 THEN '800'       -- ANALISTA DO TESOURO ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 6 THEN '720'       -- ANALISTA AUXILIAR DO TESOURO ESTADUAL
    END AS CARGO,
    'WHERE VALOR_MULTIPLICADOR <> ' AS Q_2,
    CASE
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 2 THEN '8400'   -- AUDITOR FISCAL DA FAZENDA ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 3 THEN '2880'      -- AUDITOR FISCAL AUXILIAR DA FAZENDA ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 4 THEN '1620'      -- AGENTE DE TRIBUTOS DA FAZENDA ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 5 THEN '800'       -- ANALISTA DO TESOURO ESTADUAL
        WHEN FR.ID_CATEGORIA_FUNCIONAL = 6 THEN '720'       -- ANALISTA AUXILIAR DO TESOURO ESTADUAL
    END AS VALOR,
    'AND ID_RUBRICA_IMPORTADA = ' || PAG.ID_RUBRICA_IMPORTADA || ';' AS Q_3
FROM SW_SEFAZPI.PESSOA_VINCULO PV
    JOIN SW_SEFAZPI.FUNCIONARIO F ON F.ID_PESSOA_VINCULO = PV.ID_PESSOA_VINCULO
    JOIN SW_SEFAZPI.FUNCIONARIO_REFERENCIA FR ON (FR.ID_FUNCIONARIO = F.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL)
RIGHT JOIN (
    SELECT 'ADAPI' AS ORGAO, FO.CHAVE_FOLHA, FF.COD_INSTITUCIONAL, RI.ID_RUBRICA_IMPORTADA, RI.VALOR_MULTIPLICADOR FROM SW_ADAPI.FOLHA_FUNC_RUBRICA_IMPORTADA RI JOIN SW_ADAPI.FOLHA_FUNC FF ON FF.ID_FOLHA_FUNCIONARIO = RI.ID_FOLHA_FUNCIONARIO JOIN SW_ADAPI.FOLHA FO ON FO.ID_FOLHA = FF.ID_FOLHA WHERE FO.MES = 7 AND FO.ANO = 2026 AND RI.ID_RUBRICA IN (1555799, 1555800, 1555346, 1559130, 1556100, 1559131, 1556099, 1561591)
    UNION ALL
    SELECT 'ADH' AS ORGAO, FO.CHAVE_FOLHA, FF.COD_INSTITUCIONAL, RI.ID_RUBRICA_IMPORTADA, RI.VALOR_MULTIPLICADOR FROM SW_ADH.FOLHA_FUNC_RUBRICA_IMPORTADA RI JOIN SW_ADH.FOLHA_FUNC FF ON FF.ID_FOLHA_FUNCIONARIO = RI.ID_FOLHA_FUNCIONARIO JOIN SW_ADH.FOLHA FO ON FO.ID_FOLHA = FF.ID_FOLHA WHERE FO.MES = 7 AND FO.ANO = 2026 AND RI.ID_RUBRICA IN (1555799, 1555800, 1555346, 1559130, 1556100, 1559131, 1556099, 1561591)
    UNION ALL
    SELECT 'AGESPISA' AS ORGAO, FO.CHAVE_FOLHA, FF.COD_INSTITUCIONAL, RI.ID_RUBRICA_IMPORTADA, RI.VALOR_MULTIPLICADOR FROM SW_AGESPISA.FOLHA_FUNC_RUBRICA_IMPORTADA RI JOIN SW_AGESPISA.FOLHA_FUNC FF ON FF.ID_FOLHA_FUNCIONARIO = RI.ID_FOLHA_FUNCIONARIO JOIN SW_AGESPISA.FOLHA FO ON FO.ID_FOLHA = FF.ID_FOLHA WHERE FO.MES = 7 AND FO.ANO = 2026 AND RI.ID_RUBRICA IN (1555799, 1555800, 1555346, 1559130, 1556100, 1559131, 1556099, 1561591)
    UNION ALL
